:root {
  --ink: #35312a;
  --muted: #786f61;
  --paper: #fffdf6;
  --cream: #f6edce;
  --line: #dfd2af;
  --marigold: #f6b52e;
  --orange: #df7426;
  --leaf: #55734b;
}

.stem-card {
  box-sizing: border-box;
  width: 480px;
  overflow: hidden;
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: 18px;
  color: var(--ink);
}

.card-head {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 15px 16px 13px;
  border-bottom: 1px solid var(--line);
}

.flower-mark {
  display: grid;
  width: 34px;
  height: 34px;
  flex: 0 0 auto;
  place-items: center;
  border-radius: 50%;
  background: var(--marigold);
  color: var(--orange);
  font-size: 22px;
  line-height: 1;
}

.heading {
  flex: 1;
  min-width: 0;
}

.eyebrow {
  margin: 0 0 2px;
  color: var(--muted);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.08em;
  line-height: 1.1;
  text-transform: uppercase;
}

h1 {
  margin: 0;
  font-size: 19px;
  font-weight: 750;
  line-height: 1.15;
}

.status {
  flex: 0 0 auto;
  padding: 5px 8px;
  border-radius: 999px;
  background: var(--cream);
  color: var(--orange);
  font-size: 11px;
  font-weight: 700;
  line-height: 1;
}

.bundle-list {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 8px;
  margin: 0;
  padding: 14px 16px;
  list-style: none;
}

.bundle-list li {
  display: flex;
  flex-direction: column;
  gap: 3px;
  min-height: 58px;
  justify-content: center;
  padding: 8px 10px;
  border-left: 4px solid var(--marigold);
  border-radius: 8px;
  background: var(--cream);
}

.amount {
  color: var(--orange);
  font-size: 21px;
  font-weight: 800;
  line-height: 1;
}

.label {
  color: var(--muted);
  font-size: 11px;
  font-weight: 600;
  line-height: 1.2;
}

.card-foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 11px 16px;
  background: var(--cream);
  border-top: 1px solid var(--line);
}

.pickup-note {
  margin: 0;
  color: var(--muted);
  font-size: 12px;
  line-height: 1.35;
}

.pickup-note strong {
  color: var(--ink);
  font-weight: 750;
}

button {
  padding: 8px 11px;
  border: 0;
  border-radius: 8px;
  background: var(--leaf);
  color: var(--paper);
  font-size: 12px;
  font-weight: 700;
  line-height: 1;
}
